# The `-ndk_platform` AIDL variant was merged into plain `-ndk` in Android 13, so blobs
# that still reference `*-ndk_platform` need the dep rewritten to `*-ndk`.
def lib_fixup_ndk_platform(lib: str, partition: str):
    return lib.replace('-ndk_platform', '-ndk')


lib_fixups: lib_fixups_user_type = {
    **lib_fixups,
    'android.hardware.common-V2-ndk_platform': lib_fixup_ndk_platform,
}

module = ExtractUtilsModule(
    'leap',
    'motorola',
    blob_fixups=blob_fixups,
    lib_fixups=lib_fixups,
    namespace_imports=namespace_imports,
)
# NOTE: firmware blobs (modem/radio/bluetooth/dsp partitions) handled separately later
# via a proprietary-firmware.txt; deferred for the first vendor-blob pass.

if __name__ == '__main__':
    utils = ExtractUtils.device(module)
    utils.run()
